import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import AnimatedPopup from '../components/AnimatedPopup';

// This component can be used both as a page and as a modal
const WalletModal = ({ onClose }) => {
  const { user } = useAuth();
  const [walletInfo, setWalletInfo] = useState(null);
  const [transactions, setTransactions] = useState([]);
  const [inventory, setInventory] = useState([]);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState('deposit');
  const [amount, setAmount] = useState('');
  const [address, setAddress] = useState('');
  const [showPopup, setShowPopup] = useState(false);
  const [popupMessage, setPopupMessage] = useState('');
  const [popupType, setPopupType] = useState('info');

  // Fetch wallet info, transactions, and inventory
  useEffect(() => {
    const fetchData = async () => {
      try {
        const walletRes = await fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/wallet/balance/${user?.id}`, {
          headers: {
            'Authorization': `Bearer ${localStorage.getItem('token')}`
          }
        });
        const transactionsRes = await fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/wallet/transactions/${user?.id}`, {
          headers: {
            'Authorization': `Bearer ${localStorage.getItem('token')}`
          }
        });

        const walletData = await walletRes.json();
        const transactionsData = await transactionsRes.json();

        // Mock inventory data for now - in a real app this would come from API
        const inventoryData = [
          { id: 1, name: 'Golden Coin', value: 100, rarity: 'rare', image: '/images/gold-coin.png' },
          { id: 2, name: 'Silver Token', value: 50, rarity: 'uncommon', image: '/images/silver-token.png' },
          { id: 3, name: 'Diamond Gem', value: 500, rarity: 'epic', image: '/images/diamond-gem.png' },
          { id: 4, name: 'Ruby Jewel', value: 250, rarity: 'legendary', image: '/images/ruby-jewel.png' },
        ];

        setWalletInfo(walletData);
        setTransactions(transactionsData);
        setInventory(inventoryData);
        setLoading(false);
      } catch (error) {
        console.error('Error fetching wallet data:', error);
        setLoading(false);
      }
    };

    if (user) {
      fetchData();
    }
  }, [user]);

  const showCustomPopup = (message, type = 'info') => {
    setPopupMessage(message);
    setPopupType(type);
    setShowPopup(true);

    // Auto-hide after 3 seconds
    setTimeout(() => {
      setShowPopup(false);
    }, 3000);
  };

  const handleDeposit = async () => {
    if (!amount || parseFloat(amount) <= 0) {
      showCustomPopup('Please enter a valid amount', 'error');
      return;
    }

    try {
      const response = await fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/wallet/deposit`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        },
        body: JSON.stringify({ 
          amount: parseFloat(amount),
          method: 'credit_card' // Default method
        })
      });

      const data = await response.json();

      if (response.ok) {
        showCustomPopup('Deposit request submitted successfully!', 'success');
        setAmount('');
        // Refresh data by refetching
        const walletRes = await fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/wallet/balance/${user?.id}`, {
          headers: {
            'Authorization': `Bearer ${localStorage.getItem('token')}`
          }
        });
        const walletData = await walletRes.json();
        setWalletInfo(walletData);
        setActiveTab('deposit');
      } else {
        showCustomPopup(data.message || 'Deposit failed', 'error');
      }
    } catch (error) {
      console.error('Error processing deposit:', error);
      showCustomPopup('Error processing deposit', 'error');
    }
  };

  const handleWithdraw = async () => {
    if (!amount || !address || parseFloat(amount) <= 0) {
      showCustomPopup('Please enter a valid amount and address', 'error');
      return;
    }

    if (parseFloat(amount) > (walletInfo?.available || 0)) {
      showCustomPopup('Insufficient balance', 'error');
      return;
    }

    try {
      const response = await fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/wallet/withdraw`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        },
        body: JSON.stringify({ 
          amount: parseFloat(amount),
          method: 'bank_transfer' // Default method
        })
      });

      const data = await response.json();

      if (response.ok) {
        showCustomPopup('Withdrawal request submitted successfully!', 'success');
        setAmount('');
        setAddress('');
        // Refresh data by refetching
        const walletRes = await fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/wallet/balance/${user?.id}`, {
          headers: {
            'Authorization': `Bearer ${localStorage.getItem('token')}`
          }
        });
        const walletData = await walletRes.json();
        setWalletInfo(walletData);
        setActiveTab('withdraw');
      } else {
        showCustomPopup(data.message || 'Withdrawal failed', 'error');
      }
    } catch (error) {
      console.error('Error processing withdrawal:', error);
      showCustomPopup('Error processing withdrawal', 'error');
    }
  };

  if (loading) {
    return (
      <div className="wallet-loading">
        <div className="loading-container">
          <div className="loading-spinner"></div>
          <p>Loading wallet...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="wallet-modal">
      {/* Modal header with deposit/withdraw buttons */}
      <div className="wallet-modal-header">
        <h2>Wallet & Inventory</h2>
        <div className="wallet-actions">
          <button 
            className={`modal-action-btn ${activeTab === 'deposit' ? 'active' : ''}`}
            onClick={(e) => {
              e.stopPropagation();
              setActiveTab('deposit');
            }}
          >
            Deposit
          </button>
          <button 
            className={`modal-action-btn ${activeTab === 'withdraw' ? 'active' : ''}`}
            onClick={(e) => {
              e.stopPropagation();
              setActiveTab('withdraw');
            }}
          >
            Withdraw
          </button>
          <button 
            className="modal-close-btn"
            onClick={onClose}
          >
            ×
          </button>
        </div>
      </div>

      {/* Modal content */}
      <div className="wallet-modal-content">
        {/* Inventory Section */}
        <div className="inventory-section">
          <h3>Your Items</h3>
          <div className="inventory-grid">
            {inventory.length > 0 ? (
              inventory.map((item) => (
                <div key={item.id} className="inventory-item">
                  <div className="item-image">
                    {item.image ? (
                      <img src={item.image} alt={item.name} />
                    ) : (
                      <div className="default-item-icon">💎</div>
                    )}
                  </div>
                  <div className="item-details">
                    <h4>{item.name}</h4>
                    <p className="item-value">{item.value} AMP</p>
                    <span className={`badge badge-${item.rarity}`}>
                      {item.rarity}
                    </span>
                  </div>
                </div>
              ))
            ) : (
              <p className="no-items">No items in your inventory</p>
            )}
          </div>
        </div>

        {/* Balance display */}
        <div className="wallet-balance">
          <div className="balance-card">
            <h3>Total Balance</h3>
            <div className="balance-amount">
              {walletInfo?.total?.toLocaleString() || '0'} <span className="amp-symbol">AMP</span>
            </div>
            <div className="balance-available">
              Available: {walletInfo?.available?.toLocaleString() || '0'} AMP
            </div>
          </div>

          <div className="balance-card">
            <h3>Locked Funds</h3>
            <div className="balance-amount">
              {walletInfo?.locked?.toLocaleString() || '0'} <span className="amp-symbol">AMP</span>
            </div>
          </div>
        </div>

        {/* Deposit/Withdraw Form */}
        <div className="transaction-section">
          <h3>{activeTab === 'deposit' ? 'Deposit Funds' : 'Withdraw Funds'}</h3>

          {activeTab === 'deposit' ? (
            <div className="deposit-form">
              <div className="form-group">
                <label>Amount (AMP)</label>
                <input
                  type="number"
                  value={amount}
                  onChange={(e) => setAmount(e.target.value)}
                  placeholder="Enter amount to deposit"
                  className="form-control"
                />
              </div>
              <div className="form-group">
                <label>Deposit Address</label>
                <input
                  type="text"
                  value={address}
                  onChange={(e) => setAddress(e.target.value)}
                  placeholder="Your deposit address"
                  className="form-control"
                  readOnly
                />
                <small className="form-text">Send AMP coins to this address to deposit</small>
              </div>
              <button 
                className="btn btn-success"
                onClick={handleDeposit}
              >
                Confirm Deposit
              </button>
            </div>
          ) : (
            <div className="withdraw-form">
              <div className="form-group">
                <label>Amount (AMP)</label>
                <input
                  type="number"
                  value={amount}
                  onChange={(e) => setAmount(e.target.value)}
                  placeholder="Enter amount to withdraw"
                  className="form-control"
                />
              </div>
              <div className="form-group">
                <label>Withdrawal Address</label>
                <input
                  type="text"
                  value={address}
                  onChange={(e) => setAddress(e.target.value)}
                  placeholder="Enter your wallet address"
                  className="form-control"
                />
              </div>
              <button 
                className="btn btn-danger"
                onClick={handleWithdraw}
              >
                Confirm Withdrawal
              </button>
            </div>
          )}
        </div>

        {/* Recent Transactions */}
        <div className="wallet-transactions">
          <h3>Recent Transactions</h3>
          {transactions.length > 0 ? (
            <table className="table">
              <thead>
                <tr>
                  <th>Type</th>
                  <th>Amount</th>
                  <th>Status</th>
                  <th>Date</th>
                </tr>
              </thead>
              <tbody>
                {transactions.map((transaction) => (
                  <tr key={transaction.id}>
                    <td>{transaction.type}</td>
                    <td>{transaction.amount} AMP</td>
                    <td>
                      <span className={`badge badge-${transaction.status === 'completed' ? 'success' : transaction.status === 'pending' ? 'warning' : 'danger'}`}>
                        {transaction.status}
                      </span>
                    </td>
                    <td>{new Date(transaction.timestamp).toLocaleDateString()}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          ) : (
            <p>No transactions found.</p>
          )}
        </div>
      </div>

      {/* Custom animated popup */}
      {showPopup && (
        <AnimatedPopup 
          message={popupMessage} 
          type={popupType} 
          onClose={() => setShowPopup(false)}
        />
      )}
    </div>
  );
};

// Main WalletPage component for routing
const WalletPage = () => {
  const { user } = useAuth();
  const [showWallet, setShowWallet] = useState(false);
  const [walletInfo, setWalletInfo] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchWalletInfo = async () => {
      if (user) {
        try {
          const response = await fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/wallet/balance/${user.id}`, {
            headers: {
              'Authorization': `Bearer ${localStorage.getItem('token')}`
            }
          });

          if (response.ok) {
            const data = await response.json();
            setWalletInfo(data);
          }
          setLoading(false);
        } catch (error) {
          console.error('Error fetching wallet info:', error);
          setLoading(false);
        }
      }
    };

    fetchWalletInfo();
  }, [user]);

  if (loading) {
    return (
      <div className="loading-container">
        <div className="loading-spinner"></div>
        <p>Loading wallet...</p>
      </div>
    );
  }

  return (
    <div className="wallet-page">
      <div className="page-header">
        <h1>Your Wallet</h1>
        <p>Manage your AMP coins and items</p>
      </div>

      <div className="wallet-overview">
        <div className="balance-card">
          <h2>Your Balance</h2>
          <p className="balance-amount">{walletInfo?.total?.toFixed(2) || '0.00'} AMP</p>
          <p className="balance-available">Available: {walletInfo?.available?.toFixed(2) || '0.00'} AMP</p>
          <button 
            className="btn btn-primary"
            onClick={() => setShowWallet(true)}
          >
            Open Wallet
          </button>
        </div>
      </div>

      {showWallet && (
        <div className="wallet-modal-overlay" onClick={() => setShowWallet(false)}>
          <div className="wallet-modal-content" onClick={(e) => e.stopPropagation()}>
            <WalletModal onClose={() => setShowWallet(false)} />
          </div>
        </div>
      )}
    </div>
  );
};

export default WalletPage;
